const UNITS = { d: 86400000, h: 3600000, m: 60000, s: 1000 };

// Anchored so each unit appears at most once, largest first, with nothing left
// over between groups.
const DURATION_RE = /^(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;

function parseDuration(input) {
  if (typeof input !== 'string') throw new RangeError(`invalid duration: ${input}`);
  const groups = DURATION_RE.exec(input);
  if (groups === null || groups.slice(1).every((n) => n === undefined)) {
    throw new RangeError(`invalid duration: ${input}`);
  }
  const values = groups.slice(1);
  let total = 0;
  for (const [unit, size] of Object.entries(UNITS)) {
    const n = values.find((_, i) => i === Object.keys(UNITS).indexOf(unit));
    if (n !== undefined) total += Number(n) * size;
  }
  return total;
}

function formatDuration(ms) {
  const parts = [];
  for (const [unit, size] of Object.entries(UNITS)) {
    const n = Math.floor(ms / size);
    if (n > 0) parts.push(`${n}${unit}`);
    ms -= n * size;
  }
  return parts.length > 0 ? parts.join('') : '0s';
}

